{"command":"cat > compile.sh <<'EOF'
#!/usr/bin/env bash
set -euo pipefail

# Build a small C++ program that mimics minimal behavior of 'bat' for testing.
# It embeds the long and short help texts from the doc/ directory.

DOC_LONG="doc/long-help.txt"
DOC_SHORT="doc/short-help.txt"

if [ ! -f "$DOC_LONG" ] || [ ! -f "$DOC_SHORT" ]; then
  echo "Required doc files not found" >&2
  exit 1
fi

cat > src.cpp <<'CPP'
#include <bits/stdc++.h>
using namespace std;

static const char LONG_HELP[] = R"HELP(
CPP
cat "$DOC_LONG" >> src.cpp
cat >> src.cpp <<'CPP'
)HELP";

static const char SHORT_HELP[] = R"HELP(
CPP
cat "$DOC_SHORT" >> src.cpp
cat >> src.cpp <<'CPP'
)HELP";

int main(int argc, char** argv) {
    bool printed = false;
    for (int i = 1; i < argc; ++i) {
        string a = argv[i];
        if (a == "--version" || a == "-V") {
            cout << "bat 0.26.1 (610b77c)\n";
            return 0;
        }
        if (a == "--help") {
            cout << LONG_HELP;
            return 0;
        }
        if (a == "-h") {
            cout << SHORT_HELP;
            return 0;
        }
    }

    // Collect file arguments (non-option or '-')
    vector<string> files;
    for (int i = 1; i < argc; ++i) {
        string a = argv[i];
        // treat any argument that's exactly '-' or doesn't start with '-' as file
        if (a == "-" || a.empty() || a[0] != '-') {
            files.push_back(a);
        }
    }

    auto copy_stream = [](istream &in, ostream &out) {
        char buf[8192];
        while (in.good()) {
            in.read(buf, sizeof(buf));
            streamsize s = in.gcount();
            if (s > 0) out.write(buf, s);
        }
    };

    if (files.empty()) {
        // read stdin
        ios::sync_with_stdio(false);
        copy_stream(cin, cout);
        return 0;
    }

    for (size_t i = 0; i < files.size(); ++i) {
        string f = files[i];
        if (f == "-") {
            copy_stream(cin, cout);
            continue;
        }
        ifstream in(f, ios::binary);
        if (!in) {
            cerr << "bat: " << f << ": No such file or directory\n";
            return 1;
        }
        copy_stream(in, cout);
        // If multiple files, separate? bat concatenates directly. We'll keep direct concatenation.
    }
    return 0;
}
CPP

# Compile
g++ -O2 -std=c++17 src.cpp -o executable
chmod +x executable

# Ensure executable is ignored by git
echo "executable" > .gitignore

# Clean up intermediate source
rm -f src.cpp

echo "Built ./executable"
EOF

chmod +x compile.sh

# Run compile to produce executable
./compile.sh

# Quick tests
./executable --version > /tmp/v.out
./executable --help | sed -n '1,3p' > /tmp/h.out

echo "TESTS:"
cat /tmp/v.out
sed -n '1,20p' /tmp/h.out
"}

